CREATE DATABASE IF NOT EXISTS kanban_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kanban_db;
DROP PROCEDURE IF EXISTS sp_user_create; DROP PROCEDURE IF EXISTS sp_user_find_by_username; DROP PROCEDURE IF EXISTS sp_user_list;
DROP PROCEDURE IF EXISTS sp_board_create; DROP PROCEDURE IF EXISTS sp_board_get; DROP PROCEDURE IF EXISTS sp_board_list; DROP PROCEDURE IF EXISTS sp_board_update; DROP PROCEDURE IF EXISTS sp_board_delete;
DROP PROCEDURE IF EXISTS sp_task_create; DROP PROCEDURE IF EXISTS sp_task_get; DROP PROCEDURE IF EXISTS sp_task_update; DROP PROCEDURE IF EXISTS sp_task_update_status; DROP PROCEDURE IF EXISTS sp_task_delete; DROP PROCEDURE IF EXISTS sp_task_search;
DROP PROCEDURE IF EXISTS sp_user_role_update; DROP PROCEDURE IF EXISTS sp_user_active_update;
DROP TABLE IF EXISTS tasks; DROP TABLE IF EXISTS boards; DROP TABLE IF EXISTS users;
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role ENUM('ADMIN','USER') NOT NULL DEFAULT 'USER',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE boards(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,owner_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_board_owner FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE tasks(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(180) NOT NULL,description TEXT,status ENUM('TODO','IN_PROGRESS','DONE') NOT NULL DEFAULT 'TODO',priority ENUM('LOW','MEDIUM','HIGH') NOT NULL DEFAULT 'MEDIUM',due_date DATE,board_id BIGINT NOT NULL,assignee_id BIGINT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(board_id) REFERENCES boards(id),FOREIGN KEY(assignee_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX idx_tasks_status(status),INDEX idx_tasks_priority(priority),INDEX idx_tasks_assignee(assignee_id),INDEX idx_tasks_board(board_id),INDEX idx_tasks_due(due_date));
DELIMITER $$
CREATE PROCEDURE sp_user_create(IN p_username VARCHAR(80),IN p_email VARCHAR(160),IN p_hash VARCHAR(100)) BEGIN IF EXISTS(SELECT 1 FROM users WHERE username=p_username OR email=p_email) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Usuario o email duplicado'; END IF; INSERT INTO users(username,email,password_hash) VALUES(p_username,p_email,p_hash); SELECT LAST_INSERT_ID() id; END$$
CREATE PROCEDURE sp_user_find_by_username(IN p_username VARCHAR(80)) BEGIN SELECT id,username,email,password_hash,role,active,created_at FROM users WHERE username=p_username LIMIT 1; END$$
CREATE PROCEDURE sp_user_list(IN p_page INT,IN p_size INT) BEGIN SELECT id,username,email,role,active,created_at,COUNT(*) OVER() total_elements FROM users ORDER BY id LIMIT LEAST(GREATEST(p_size,1),50) OFFSET GREATEST(p_page,0)*LEAST(GREATEST(p_size,1),50); END$$
CREATE PROCEDURE sp_board_create(IN p_name VARCHAR(120),IN p_owner BIGINT) BEGIN INSERT INTO boards(name,owner_id) VALUES(p_name,p_owner); SELECT id,name,owner_id,created_at FROM boards WHERE id=LAST_INSERT_ID(); END$$
CREATE PROCEDURE sp_board_get(IN p_id BIGINT,IN p_actor BIGINT) BEGIN IF NOT EXISTS(SELECT 1 FROM boards b JOIN users u ON u.id=p_actor WHERE b.id=p_id AND (u.role='ADMIN' OR b.owner_id=p_actor)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Board no encontrado o acceso denegado'; END IF; SELECT b.* FROM boards b WHERE b.id=p_id; END$$
CREATE PROCEDURE sp_board_list(IN p_actor BIGINT) BEGIN SELECT b.* FROM boards b JOIN users u ON u.id=p_actor WHERE u.role='ADMIN' OR b.owner_id=p_actor ORDER BY b.id; END$$
CREATE PROCEDURE sp_board_update(IN p_id BIGINT,IN p_name VARCHAR(120),IN p_actor BIGINT) BEGIN UPDATE boards b JOIN users u ON u.id=p_actor SET b.name=p_name WHERE b.id=p_id AND (u.role='ADMIN' OR b.owner_id=p_actor); IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Board no encontrado o sin cambios'; END IF; END$$
CREATE PROCEDURE sp_board_delete(IN p_id BIGINT,IN p_actor BIGINT) BEGIN DELETE b FROM boards b JOIN users u ON u.id=p_actor WHERE b.id=p_id AND (u.role='ADMIN' OR b.owner_id=p_actor); IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Board no encontrado'; END IF; END$$
CREATE PROCEDURE sp_task_create(IN p_title VARCHAR(180),IN p_description TEXT,IN p_status VARCHAR(20),IN p_priority VARCHAR(20),IN p_due DATE,IN p_board BIGINT,IN p_assignee BIGINT,IN p_actor BIGINT) BEGIN IF NOT EXISTS(SELECT 1 FROM boards b JOIN users u ON u.id=p_actor WHERE b.id=p_board AND (u.role='ADMIN' OR b.owner_id=p_actor)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Board no encontrado o acceso denegado'; END IF; INSERT INTO tasks(title,description,status,priority,due_date,board_id,assignee_id,created_by) VALUES(p_title,p_description,p_status,p_priority,p_due,p_board,p_assignee,p_actor); SELECT * FROM tasks WHERE id=LAST_INSERT_ID(); END$$
CREATE PROCEDURE sp_task_get(IN p_id BIGINT,IN p_actor BIGINT) BEGIN IF NOT EXISTS(SELECT 1 FROM tasks t JOIN boards b ON b.id=t.board_id JOIN users u ON u.id=p_actor WHERE t.id=p_id AND t.deleted=FALSE AND (u.role='ADMIN' OR b.owner_id=p_actor)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Task no encontrado o acceso denegado'; END IF; SELECT t.* FROM tasks t WHERE t.id=p_id AND t.deleted=FALSE; END$$
CREATE PROCEDURE sp_task_update(IN p_id BIGINT,IN p_title VARCHAR(180),IN p_description TEXT,IN p_status VARCHAR(20),IN p_priority VARCHAR(20),IN p_due DATE,IN p_board BIGINT,IN p_assignee BIGINT,IN p_actor BIGINT) BEGIN UPDATE tasks t JOIN boards b ON b.id=t.board_id JOIN users u ON u.id=p_actor SET t.title=p_title,t.description=p_description,t.status=p_status,t.priority=p_priority,t.due_date=p_due,t.board_id=p_board,t.assignee_id=p_assignee WHERE t.id=p_id AND t.deleted=FALSE AND (u.role='ADMIN' OR b.owner_id=p_actor); IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Task no encontrado o acceso denegado'; END IF; END$$
CREATE PROCEDURE sp_task_update_status(IN p_id BIGINT,IN p_status VARCHAR(20),IN p_actor BIGINT) BEGIN UPDATE tasks t JOIN boards b ON b.id=t.board_id JOIN users u ON u.id=p_actor SET t.status=p_status WHERE t.id=p_id AND t.deleted=FALSE AND (u.role='ADMIN' OR b.owner_id=p_actor); IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Task no encontrado'; END IF; END$$
CREATE PROCEDURE sp_task_delete(IN p_id BIGINT,IN p_actor BIGINT) BEGIN UPDATE tasks t JOIN boards b ON b.id=t.board_id JOIN users u ON u.id=p_actor SET t.deleted=TRUE WHERE t.id=p_id AND t.deleted=FALSE AND (u.role='ADMIN' OR b.owner_id=p_actor); IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Task no encontrado'; END IF; END$$
CREATE PROCEDURE sp_task_search(IN p_actor BIGINT,IN p_board BIGINT,IN p_status VARCHAR(20),IN p_priority VARCHAR(20),IN p_assignee BIGINT,IN p_q VARCHAR(200),IN p_from DATE,IN p_to DATE,IN p_sort VARCHAR(30),IN p_dir VARCHAR(4),IN p_page INT,IN p_size INT) BEGIN
 DECLARE v_sort VARCHAR(30); DECLARE v_dir VARCHAR(4); SET v_sort=IF(p_sort IN('created_at','updated_at','due_date','priority','status','title','id'),p_sort,'created_at'); SET v_dir=IF(UPPER(p_dir)='ASC','ASC','DESC');
 SET @q=CONCAT('SELECT t.*,COUNT(*) OVER() total_elements FROM tasks t JOIN boards b ON b.id=t.board_id JOIN users u ON u.id=? WHERE t.deleted=FALSE AND (u.role=''ADMIN'' OR b.owner_id=?) AND (? IS NULL OR t.board_id=?) AND (? IS NULL OR t.status=?) AND (? IS NULL OR t.priority=?) AND (? IS NULL OR t.assignee_id=?) AND (? IS NULL OR t.title LIKE CONCAT(''%'',? ,''%'')) AND (? IS NULL OR t.due_date>=?) AND (? IS NULL OR t.due_date<=?) ORDER BY ',v_sort,' ',v_dir,' LIMIT ? OFFSET ?');
 PREPARE s FROM @q; SET @actor=p_actor,@board=p_board,@status=p_status,@priority=p_priority,@assignee=p_assignee,@query=p_q,@from=p_from,@to=p_to,@lim=LEAST(GREATEST(p_size,1),50),@off=GREATEST(p_page,0)*LEAST(GREATEST(p_size,1),50);
 EXECUTE s USING @actor,@actor,@board,@board,@status,@status,@priority,@priority,@assignee,@assignee,@query,@query,@from,@from,@to,@to,@lim,@off; DEALLOCATE PREPARE s; END$$
CREATE PROCEDURE sp_user_role_update(IN p_id BIGINT,IN p_role VARCHAR(10)) BEGIN UPDATE users SET role=p_role WHERE id=p_id; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Usuario no encontrado'; END IF; END$$
CREATE PROCEDURE sp_user_active_update(IN p_id BIGINT,IN p_active BOOLEAN) BEGIN UPDATE users SET active=p_active WHERE id=p_id; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Usuario no encontrado'; END IF; END$$
DELIMITER ;
